func (db *DB) Decisions(ctx context.Context, projectID int64, pendingOnly bool) ([]Decision, error) {
	if err := db.ObsoleteResolvedDecisions(ctx, projectID); err != nil {
		return nil, err
	}
	return db.listDecisions(ctx, projectID, pendingOnly)
}

// PendingDecisions lists unanswered Decisions without first marking resolved
// ones obsolete, so read commands work while the store is contended.
func (db *DB) PendingDecisions(ctx context.Context, projectID int64) ([]Decision, error) {
	query := decisionSelect + `
		WHERE d.project_id=? AND d.answered_at=0 AND d.obsolete_at=0
		AND EXISTS (SELECT 1 FROM tasks t WHERE t.id=d.task_id AND NOT (` + resolvedDecisionPredicate + `))
		ORDER BY d.id`
	rows, err := db.QueryContext(ctx, query, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	decisions := []Decision{}
	for rows.Next() {
		decision, err := decisionRow(rows)
		if err != nil {
			return nil, err
		}
		decisions = append(decisions, decision)
	}
	return decisions, rows.Err()
}

func (db *DB) listDecisions(ctx context.Context, projectID int64, pendingOnly bool) ([]Decision, error) {
	query := decisionSelect + ` WHERE project_id=?`
	if pendingOnly {
		query += ` AND answered_at=0 AND obsolete_at=0`
	}
	rows, err := db.QueryContext(ctx, query+` ORDER BY id`, projectID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	decisions := []Decision{}
	for rows.Next() {
		decision, err := decisionRow(rows)
		if err != nil {
			return nil, err
		}
		decisions = append(decisions, decision)
	}
	return decisions, rows.Err()
}

