// ObsoleteStaleReviewCapDecisions retires unanswered cap choices for an older
// exact head, preserving answered history.
func (db *DB) ObsoleteStaleReviewCapDecisions(ctx context.Context, taskID int64, currentOrigin string) error {
	var projectID int64
	if err := db.QueryRowContext(ctx, `SELECT project_id FROM tasks WHERE id=?`, taskID).Scan(&projectID); err != nil {
		return err
	}
	result, err := db.ExecContext(ctx, `UPDATE decisions SET obsolete_at=?,obsolete_reason='Review candidate head changed'
WHERE task_id=? AND kind='review_cap' AND answered_at=0 AND obsolete_at=0 AND origin<>?`, time.Now().UnixMilli(), taskID, currentOrigin)
	if err != nil {
		return err
	}
	changed, err := result.RowsAffected()
	if err != nil || changed == 0 {
		return err
	}
	return db.PersistProject(ctx, projectID)
}

func (db *DB) ObsoletePendingReviewCapDecisions(ctx context.Context, taskID, disputeDecisionID int64) error {
	reason := fmt.Sprintf("Superseded by Greenhouse dispute Decision #%d", disputeDecisionID)
	result, err := db.ExecContext(ctx, `UPDATE decisions SET obsolete_at=?,obsolete_reason=?
WHERE task_id=? AND kind='review_cap' AND answered_at=0 AND obsolete_at=0`, time.Now().UnixMilli(), reason, taskID)
	if err != nil {
		return err
	}
	changed, err := result.RowsAffected()
	if err != nil || changed == 0 {
		return err
	}
	var projectID int64
	if err := db.QueryRowContext(ctx, `SELECT project_id FROM tasks WHERE id=?`, taskID).Scan(&projectID); err != nil {
		return err
	}
	return db.PersistProject(ctx, projectID)
}

// ObsoletePendingMergeReadyDecisions retires unanswered merge-ready choices
// after review invalidates the Task's readiness.
func (db *DB) ObsoletePendingMergeReadyDecisions(ctx context.Context, taskID int64, reason string) error {
	result, err := db.ExecContext(ctx, `UPDATE decisions SET obsolete_at=?,obsolete_reason=?
		WHERE task_id=? AND kind='merge_ready' AND answered_at=0 AND obsolete_at=0`, time.Now().UnixMilli(), reason, taskID)
	if err != nil {
		return err
	}
	changed, err := result.RowsAffected()
	if err != nil || changed == 0 {
		return err
	}
	var projectID int64
	if err := db.QueryRowContext(ctx, `SELECT project_id FROM tasks WHERE id=?`, taskID).Scan(&projectID); err != nil {
		return err
	}
	return db.PersistProject(ctx, projectID)
}

